function derived(P,S,A,M){const T=P+S+A+M,p=Math.max(0,P-10),s=Math.max(0,S-10),x=Math.max(0,A+M-20);return{hp:Math.floor(100+.5*(T-100)+2*p+Math.max(0,p-20)),sp:Math.floor(20+.1*(T-100)+.4*p+s),mp:Math.floor(x<=50?2*x:100+.5*(x-50))}}
function initUnit(source,enemy=false){const o=JSON.parse(JSON.stringify(source)),d=derived(o.PHY,o.SKL,o.ARC,o.MND),ar=ARM[o.armor]||{p:0,m:0,w:0};return{...o,enemy,maxHp:enemy?o.hp:d.hp,hp:enemy?o.hp:d.hp,maxSp:d.sp,sp:d.sp,maxMp:d.mp,mp:d.mp,physDef:enemy?o.physDef:o.PHY+ar.p,magDef:enemy?o.magDef:o.ARC+o.MND+ar.m,wi:0,weapon:enemy?o.weapon:W[o.weapons[0]],alive:true,defending:false,status:{poison:0,blind:0,sleep:0,agitate:0,stun:0,headBind:0,armBind:0,legBind:0},statusPower:{},statusBuildup:{},interrupts:0,casting:null,queued:null}}
function weaponByName(n){return Object.values(W).find(w=>w.name===n)||null}
function battleLoad(u){const arm=ARM[u.armor]||{w:0},off=weaponByName(u.currentOffhand||'');return (u.weapon?.load||0)+(off?.load||0)+arm.w*4+1}
function updateEncumbrance(u){const load=battleLoad(u),limit=Math.max(1,u.PHY),ratio=load/limit;u.encumbrance={weight:load,limit,ratio,level:ratio<=1?0:ratio<=1.2?1:ratio<=1.5?2:3};return u.encumbrance}
function current(){return party[idx]}
function weaponPassive(u,a,t){const n=u.weapon?.name||'';let m=1;if(/戦槌|槌/.test(n)&&Math.random()<.12)t.status.stun=1;if(/戦斧|斧/.test(n)&&/重装|守護機|番人/.test(t.style+t.name))m*=1.15;if(/短剣/.test(n)&&Object.values(t.status).some(v=>v>0))m*=1.12;if(/槍/.test(n)&&t.row==='back')m*=1.08;if(/鎌/.test(n)&&t.hp/t.maxHp<.35)m*=1.18;if(/刀/.test(n))u.tempCrit=8;if(/弓/.test(n)&&/飛行|翼/.test(t.style+t.name))m*=1.2;if(/銃/.test(n))u.tempHit=8;if(/杖/.test(n)&&a.kind==='spell')m*=1.08;if(/盾/.test(n))u.guardBonus=Math.max(u.guardBonus||0,.08);return m}function normal(u){return{name:'通常攻撃',kind:'attack',range:u.weapon?.range||'near',attr:u.weapon?.attr||'壊',target:'enemy',scope:'single',mult:1,hit:0,speed:0}}
function getDraft(u){if(!drafts.has(u.id))drafts.set(u.id,{key:'attack',targetId:null});return drafts.get(u.id)}
function actionFor(u,key=getDraft(u).key){return key==='attack'?normal(u):u.skills[Number(key)]||normal(u)}
function canReach(a,t,r){if(!t?.alive||t.hp<=0)return false;if(r==='far'||r==='all')return true;const side=t.enemy?enemies:party;const tr=live(side).some(x=>x.row==='front')?t.row:'front';return r==='mid'?tr==='front'||a.row==='front':a.row==='front'&&tr==='front'}
function targets(u,a){if(a.revive)return party.filter(x=>!x.alive);return a.target==='ally'?live(party):live(enemies).filter(t=>canReach(u,t,a.range))}
function enough(u,a){return !a.costType||u[a.costType.toLowerCase()]>=a.cost}
function unavailable(u,a){const n=a.name||'';if(u.status.headBind>0&&(a.kind==='spell'||/歌|詠唱|祈|呪|符|神|聖|幻|夢|感応|透視|索敵/.test(n)))return'頭封じ';if(u.status.armBind>0&&((a.kind==='attack')||(a.kind==='skill'&&!/歌|舞|号令|奏|念|祈|符|呪/.test(n))))return'腕封じ';if(u.status.legBind>0&&/蹴|舞|跳|突進|移動|回避/.test(n))return'脚封じ';if(!enough(u,a))return a.costType+'不足';if(!targets(u,a).length)return'射程内に対象なし';return''}
function cancelCasting(u){if(!u?.casting)return;u.casting=null;if(u.queued?.type==='cast')u.queued=null;notify(u.name+'は詠唱を中止した')}
function freeColumn(row,side=party){const used=new Set(live(side).filter(x=>x.row===row).map(col));for(let i=1;i<=3;i++)if(!used.has(i))return i;return null}
function affectedTargets(u,t,a){const side=t.enemy?enemies:party,ls=live(side),scope=a.scope||(a.rowAttack?'row':'single');if(scope==='all')return ls;if(scope==='row')return ls.filter(x=>x.row===t.row);if(scope==='adjacent')return ls.filter(x=>x.row===t.row&&Math.abs(col(x)-col(t))<=1);if(scope==='pierce')return ls.filter(x=>col(x)===col(t));if(scope==='random'){const pool=[...ls],out=[],count=Math.min(a.randomCount||3,pool.length);while(out.length<count){out.push(pool.splice(Math.floor(Math.random()*pool.length),1)[0])}return out}return[t]}
function forceMoveChance(a,t,act){const st=act.stat==='ARC'?a.ARC:act.stat==='MND'?a.MND:act.stat==='SKL'?a.SKL:a.PHY,size={small:-10,normal:0,large:20,huge:40}[t.size||'normal']||0,terrainBonus=/崖際/.test(terrain.name||'')?15:0;return clamp(70+st-t.PHY-size+terrainBonus,5,95)}
function ensureTarget(u,a){const d=getDraft(u),ts=targets(u,a);if(!ts.some(t=>t.id===d.targetId))d.targetId=ts[0]?.id||null;return ts}
function editable(){return !busy&&!over}
function notify(text){clearTimeout(noticeTimer);$('notice').textContent=text;$('notice').hidden=false;noticeTimer=setTimeout(()=>$('notice').hidden=true,2300)}
function log(text,cls=''){const el=document.createElement('div');el.textContent=text;el.className=cls;const box=$('log'),atEnd=box.scrollTop+box.clientHeight>=box.scrollHeight-24;box.append(el);$('logCount').textContent=++logCount;$('lastLog').textContent=text;$('lastLog').className='last-log '+cls;if(atEnd)box.scrollTop=box.scrollHeight}
function createCard(u){const el=document.createElement('button');el.type='button';el.className='unit '+(u.enemy?'enemy-card':'ally-card');el.dataset.unitId=u.id;el.dataset.style=u.style;el.style.gridColumn=col(u);const keys=u.enemy?['hp']:['hp','sp','mp'];el.innerHTML='<span class="card-surface"><img class="portrait" src="images/'+PORTRAITS[u.id]+'.svg" alt="" draggable="false"></span><span class="card-name">'+esc(u.name)+'</span><span class="card-status"></span><span class="queued-mark" title="入力済み" hidden>✓</span><span class="resource-list">'+keys.map(k=>'<span class="resource" data-resource="'+k+'"><span class="resource-value"><span>'+k.toUpperCase()+'</span><b></b></span><span class="bar '+(k==='hp'?'':k)+'"><i></i></span></span>').join('')+'</span>';el.querySelector('img').addEventListener('error',ev=>{ev.target.style.opacity='0'});el.addEventListener('click',()=>cardTap(u.id));nodes.set(u.id,el);return el}
function renderCards(){for(const [list,front,back] of [[enemies,'ef','eb'],[party,'pf','pb']]){for(const row of ['front','back']){const box=$(row==='front'?front:back),rowUnits=[...list].filter(u=>u.row===row).sort((a,b)=>a.slot-b.slot),maxCol=Math.max(3,...rowUnits.map(col));box.style.gridTemplateColumns='repeat('+maxCol+',minmax(0,1fr))';for(const u of rowUnits){const el=nodes.get(u.id)||createCard(u);box.append(el);if(u.enemy&&u.size==='huge'){box.style.gridTemplateColumns='repeat(3,minmax(0,1fr))';el.style.gridColumn='1 / span 3'}else if(u.enemy&&u.size==='large'&&rowUnits.length===1){el.style.gridColumn='1 / span 2'}else el.style.gridColumn=col(u);el.classList.toggle('dead',!u.alive);el.classList.toggle('active',!busy&&!over&&!u.enemy&&u.id===current()?.id);el.querySelector('.queued-mark').hidden=busy||over||!u.queued;const extraIcons={blind:'盲',sleep:'眠',agitate:'揺'};const sts=!u.alive?'<span class="status-chip">戦闘不能</span>':STATUS.filter(([k])=>u.status[k]>0).map(([k,n,s])=>'<span class="status-chip" title="'+n+' '+u.status[k]+'ターン">'+s+'</span>').join('')+Object.keys(EXTRA_STATUS).filter(k=>u.status[k]>0).map(k=>'<span class="status-chip" title="'+EXTRA_STATUS[k]+' '+u.status[k]+'ターン">'+extraIcons[k]+'</span>').join('');el.querySelector('.card-status').innerHTML=sts;el.querySelectorAll('[data-resource]').forEach(box=>{const k=box.dataset.resource,m=u['max'+k[0].toUpperCase()+k.slice(1)],v=Math.max(0,u[k]);box.querySelector('b').textContent=v;box.querySelector('i').style.width=(m?clamp(v/m*100,0,100):0)+'%'});el.setAttribute('aria-label',u.name+'、'+(u.row==='front'?'前列':'後列')+'、HP '+u.hp+(u.queued?'、入力済み':''));}}}highlightTargets()}
function highlightTargets(){const u=current(),a=u?actionFor(u):null,ts=editable()&&a?ensureTarget(u,a):[],valid=new Set(ts.map(t=>t.id)),chosen=u?getDraft(u).targetId:null;nodes.forEach((el,id)=>{el.classList.toggle('target-valid',valid.has(id));el.classList.toggle('target-selected',valid.has(id)&&id===chosen);el.classList.toggle('target-unavailable',editable()&&!valid.has(id)&&el.classList.contains('enemy-card'))})}
function effectText(a){const out=[];if(a.heal)out.push('HP回復');else out.push('威力 ×'+a.mult);for(const[k,n]of STATUS){if(a[k])out.push(n+' 基礎'+a[k]+'%')}if(a.critBonus)out.push('会心率＋'+a.critBonus);return out.join(' / ')}
function enemyIntent(){const scout=party.some(u=>u.masteries?.some(x=>/敵察知|予知|感応|索敵/.test(x)));return live(enemies).map(e=>{if(e.telegraph)return '⚠ '+e.name+'：'+e.telegraph.telegraphText;var base=/神官|魔術師/.test(e.style)?'術式':/呪術師/.test(e.style)?'妨害':/重装/.test(e.style)?'攻撃/防御':/飛行/.test(e.style)?'後列攻撃':/獣/.test(e.style)?'低HP狙い':'攻撃';return e.name+'：'+base+(scout?' / '+(e.row==='front'?'前列':'後列')+' / HP'+Math.round(e.hp/e.maxHp*100)+'%':'')}).join(' ｜ ')}
