function enemyDanger(e){const s=(e.style||'')+(e.name||'');if(e.telegraph)return e.telegraph.telegraphText;if(/BOSS/.test(e.style))return'複数フェーズ・予兆攻撃';if(/魔術師|神官/.test(s))return'遠距離術式。頭封じで行動を制限可能';if(/呪術師/.test(s))return'状態異常・動揺を使用';if(/飛行/.test(s))return'後列を狙いやすく、突・遠距離が有効';if(/重装/.test(s))return'防御行動・列攻撃を使用';if(/獣/.test(s))return'低HPの対象を優先';return'行動傾向は調査中'}
function openEnemyInfo(){const known=EXPCTX?.enemyKnowledge||{};$('sheetKicker').textContent='ENEMY INFO';$('sheetTitle').textContent='敵情報';const list=$('sheetList');list.replaceChildren();for(const e of enemies){const key=enemyBaseName(e.name),d=known[key]||known[e.name],b=document.createElement('button');b.type='button';b.className='skill-option';b.innerHTML='<b>'+esc(e.name)+'　'+(e.row==='front'?'前列':'後列')+'</b><span class="cost">'+esc(e.style||'敵')+'</span><span class="skill-meta">'+(d?'物理 '+esc(d.physical||'未判明')+' / 魔法 '+esc(d.magic||'未判明'):'弱点・耐性：未判明')+'</span><span class="skill-effect">'+(d?'異常 '+esc(d.status||'未判明')+' / ':'')+esc(enemyDanger(e))+'</span>';list.append(b)}sheet.showModal()}
function render(){renderCards();$('round').innerHTML='R<span>'+round+'</span>';$('actorName').textContent=over?'戦闘終了':busy?'戦闘中':current()?.name||'';$('actorJob').textContent=busy?(paused?'一時停止中':''):over?'':current()?.casting?'詠唱中・別行動で中止':current()?.style||'';$('actor').disabled=!editable();$('new').title=busy?'進行中の戦闘をリセット':'新しい戦闘';$('auto').disabled=!editable();$('resolve').disabled=!editable()||!live(party).every(u=>u.queued);for(const id of ['queue','swap','defend','escape','switch','actionButton','rowChange','carry','enemyInfo'])$(id).disabled=!editable();const intent=$('enemyIntent');if(intent)intent.textContent=enemyIntent();$('terrainEffect').innerHTML='<b>'+esc(terrain.name)+'</b>'+esc(terrain.desc+(terrain.extraDesc?' / '+terrain.extraDesc:''));$('pace').textContent=paceOptions[paceIndex].name;if(!editable())return;const u=current(),a=actionFor(u);ensureTarget(u,a);$('actionName').textContent=a.kind==='attack'?u.weapon.name+' · 通常攻撃':a.name;$('actionMeta').textContent=scopeName(a)+' / '+rangeName(a.range)+' / '+a.attr+(a.costType?' / '+a.costType+' '+a.cost:'');const t=(a.target==='ally'?party:enemies).find(t=>t.id===getDraft(u).targetId),bad=unavailable(u,a);$('queue').disabled=!!bad;$('swap').disabled=u.status.legBind>0||!live(party).some(t=>t.row!==u.row);$('rowChange').disabled=u.status.legBind>0||live(party).filter(t=>t.row!==u.row).length>=3;$('escape').disabled=u.status.legBind>0||!!EXPCTX?.boss;$('targetHint').innerHTML=bad?esc(bad):t?'→ '+esc(t.name)+(a.heal?' · HP '+t.hp:affinity(t,a.attr)>1?' <strong>· '+esc(a.attr)+'弱点</strong>':''):'';highlightTargets()}
function cardTap(id){if(!editable())return;const t=[...party,...enemies].find(u=>u.id===id);if(!t?.alive)return;const u=current(),a=actionFor(u);if(t.enemy||a.target==='ally'){if(!targets(u,a).some(x=>x.id===id)){notify('この行動は届きません');return}getDraft(u).targetId=id;render();return}selectActor(id)}
function selectActor(id){const i=party.findIndex(u=>u.id===id&&u.alive);if(i<0||!editable())return;idx=i;render()}
function advance(){let next=-1;for(let step=1;step<=party.length;step++){const i=(idx+step)%party.length;if(party[i].alive&&!party[i].queued){next=i;break}}if(next>=0)idx=next;phase=next<0?'ready':'command';render()}
function queue(){if(!editable())return;const u=current(),a=actionFor(u),reason=unavailable(u,a);if(reason){notify(reason);return}if(u.casting)cancelCasting(u);u.defending=false;u.queued={type:a.kind==='attack'?'attack':'skill',action:a,targetId:getDraft(u).targetId};advance()}
function simpleCommand(type){if(!editable())return;const u=current();if(type==='swap')return openSwapSheet();if((type==='escape')&&EXPCTX?.boss)return notify('ボス戦では逃走できません');if((type==='escape')&&u.status.legBind>0)return notify('脚封じで逃走できません');if(u.casting)cancelCasting(u);u.defending=type==='defend';u.queued={type};advance()}
function openSwapSheet(){if(!editable())return;const u=current();if(u.status.legBind>0)return notify('脚封じで列交代できません');const opts=live(party).filter(x=>x.id!==u.id&&x.row!==u.row);if(!opts.length)return notify('反対列に交代できる味方がいません');$('sheetKicker').textContent=u.name+' / 列交代';$('sheetTitle').textContent='交代相手を選択';const list=$('sheetList');list.replaceChildren();for(const m of opts){const b=document.createElement('button');b.type='button';b.className='member-option';b.innerHTML='<img src="images/'+PORTRAITS[m.id]+'.svg" alt=""><span>'+esc(m.name)+'<small>'+(m.row==='front'?'前列':'後列')+'</small></span><span class="cost">交代</span>';b.addEventListener('click',()=>{if(u.casting)cancelCasting(u);u.defending=false;u.queued={type:'swap',swapId:m.id};closeSheet();advance()});list.append(b)}sheet.showModal()}
function closeSheet(){if(sheet.open)sheet.close()}
function openSheet(mode='skills'){if(!editable())return;const u=current();$('sheetKicker').textContent=mode==='members'?'PARTY':u.name+' / '+u.style;$('sheetTitle').textContent=mode==='members'?'メンバーを変更':'行動を選択';const list=$('sheetList');list.replaceChildren();if(mode==='members'){for(const m of party){const b=document.createElement('button');b.type='button';b.className='member-option';b.disabled=!m.alive;b.innerHTML='<img src="images/'+PORTRAITS[m.id]+'.svg" alt=""><span>'+esc(m.name)+'<small>'+esc(m.style)+'</small></span><span class="cost">'+(!m.alive?'戦闘不能':m.queued?'入力済み':'未入力')+'</span>';b.addEventListener('click',()=>{closeSheet();selectActor(m.id)});list.append(b)}}else{for(const[key,a]of [['attack',normal(u)],...u.skills.map((s,i)=>[String(i),s])]){const reason=unavailable(u,a),b=document.createElement('button');b.type='button';b.className='skill-option'+(getDraft(u).key===key?' chosen':'');b.dataset.action=key;b.setAttribute('aria-disabled',String(!!reason));b.innerHTML='<b>'+esc(a.kind==='attack'?u.weapon.name+' · 通常攻撃':a.name)+'</b><span class="cost">'+(a.costType?a.costType+' '+a.cost:'消費なし')+'</span><span class="skill-meta">'+scopeName(a)+' / '+rangeName(a.range)+' / '+a.attr+'</span><span class="skill-effect">'+esc(reason||effectText(a))+'</span>';b.addEventListener('click',()=>{if(reason){notify(reason);return}getDraft(u).key=key;ensureTarget(u,a);closeSheet();render()});list.append(b)}}sheet.showModal()}
/* Playback has a session token: resetting never leaves an old async turn running. */
async function waitRead(text,token,min=1000){skip=false;let remaining=Math.min(3000,Math.max(min,650+[...text].length*40))*paceOptions[paceIndex].scale,last=performance.now();while(remaining>0){check(token);await new Promise(r=>setTimeout(r,35));check(token);const now=performance.now();if(!paused){if(skip)break;remaining-=now-last}last=now}skip=false}
function clearEffects(){nodes.forEach(el=>el.classList.remove('battle-acting','battle-hit','battle-heal','battle-switch'));document.querySelectorAll('.floating').forEach(el=>el.remove())}
function floating(id,value,kind='damage',label=''){const el=nodes.get(id);if(!el)return;const f=document.createElement('span');f.className='floating'+(kind==='heal'?' heal':'');f.innerHTML=(label?'<small>'+esc(label)+'</small>':'')+esc((kind==='heal'?'+':'−')+value);el.append(f);setTimeout(()=>f.remove(),1250)}
async function say(text,token,cls='',visual=null,history=true){check(token);clearEffects();$('battleMessage').className='battle-message '+cls;$('battleMessageText').textContent=text;if(history)log(text,cls);if(visual?.actorId)nodes.get(visual.actorId)?.classList.add('battle-acting');if(visual?.targetId){nodes.get(visual.targetId)?.classList.add(visual.heal?'battle-heal':'battle-hit');if(visual.value!==undefined)floating(visual.targetId,visual.value,visual.heal?'heal':'damage',visual.label||'')}await waitRead(text,token)}
function setBattle(on){$('commandPanel').classList.toggle('resolving',on);$('battleMessage').hidden=!on;if(!on){$('battleMessageText').textContent='';clearEffects()}}
async function animateSwap(a,b,text,token){check(token);clearEffects();const before=new Map([a,b].map(u=>[u.id,nodes.get(u.id).getBoundingClientRect()]));const row=a.row,slot=a.slot;a.row=b.row;a.slot=b.slot;b.row=row;b.slot=slot;render();$('battleMessage').className='battle-message sys';$('battleMessageText').textContent=text;log(text,'sys');const animations=[];for(const[u,i]of [[a,0],[b,1]]){const el=nodes.get(u.id),from=before.get(u.id),to=el.getBoundingClientRect(),dx=from.left-to.left,dy=from.top-to.top,w=i?4:-4;el.style.zIndex='10';const frames=[{transform:`translate(${dx}px,${dy}px)`,offset:0},{transform:`translate(${dx*.72+w}px,${dy*.72}px) rotate(${i?1:-1}deg)`,offset:.28},{transform:`translate(${dx*.4-w}px,${dy*.4}px) rotate(${i?-1:1}deg)`,offset:.6},{transform:'translate(0,0) rotate(0deg)',offset:1}];if(typeof el.animate==='function'){const anim=el.animate(reduced?[{opacity:.7},{opacity:1}]:frames,{duration:reduced?100:1150*paceOptions[paceIndex].scale,easing:'ease-in-out',fill:'both'});activeAnimations.add(anim);animations.push(anim.finished.catch(()=>{}).then(()=>{anim.cancel();activeAnimations.delete(anim);el.style.zIndex=''}))}else el.style.zIndex=''}await Promise.all(animations);check(token);await waitRead(text,token,350)}
async function switchWeapon(){if(!editable())return;const u=current();if(u.status.armBind>0)return notify('腕封じで換装できません。');const token=session;busy=true;closeSheet();setBattle(true);switchCounts[u.id]=(switchCounts[u.id]||0)+1;u.wi=u.wi?0:1;u.weapon=W[u.weapons[u.wi]]||u.weapon;if(u.handSets){const offIndex=u.wi?3:1,offName=u.handSets[offIndex]?.split('：')[1]||'なし';u.currentOffhand=offName;u.dualWield=offName!=='なし'&&!/盾/.test(offName);u.shieldGuard=/盾/.test(offName)?.12:0;}updateEncumbrance(u);render();nodes.get(u.id)?.classList.add('battle-switch');$('playbackTitle').textContent='換装';$('battleMessageText').textContent=u.name+'は'+u.weapon.name+'へ換装！';try{await waitRead($('battleMessageText').textContent,token,700)}catch(e){if(e!==CANCEL)throw e}finally{if(token===session){busy=false;setBattle(false);render()}}}
function typeAffinity(t,a){const s=(t.style||'')+(t.name||'');if(/重装|守護機|機械|ゴーレム|番人/.test(s))return a==='壊'?2:a==='斬'?.5:1;if(/飛行|翼|鳥/.test(s))return a==='突'?2:a==='壊'?.5:1;if(/獣/.test(s))return a==='斬'?2:1;if(/亡者|死霊/.test(s))return a==='壊'?2:a==='突'?.5:1;if(/植物|樹母/.test(s))return a==='斬'?2:1;return 1}
