function fresh(){session++;discoveredWeakness=new Set();switchCounts={};for(const anim of activeAnimations)anim.cancel();activeAnimations.clear();closeSheet();clearEffects();nodes.clear();for(const id of ['eb','ef','pf','pb'])$(id).replaceChildren();drafts.clear();replacementUsed.party.clear();replacementUsed.enemies.clear();party=HT.map(u=>initUnit(u));enemies=ET.map(u=>initUnit(u,true));terrain=TERRAINS[Math.floor(Math.random()*TERRAINS.length)];applyExploreContext();round=1;idx=0;phase='command';busy=false;over=false;paused=false;skip=false;logCount=0;$('pause').textContent='一時停止';$('pause').setAttribute('aria-pressed','false');$('log').replaceChildren();$('history').open=false;$('notice').hidden=true;setBattle(false);log('戦闘開始 · '+terrain.name,'sys');render()}
